39	
40	/**
41	 * One of the NN NameNodes acting as the target of an administrative command
42	 * (e.g. failover).
43	 */
44	@InterfaceAudience.Private
45	public class NNHAServiceTarget extends HAServiceTarget {
46	
47	  // Keys added to the fencing script environment
48	  private static final String NAMESERVICE_ID_KEY = "nameserviceid";
49	  private static final String NAMENODE_ID_KEY = "namenodeid";
50	  
51	  private final InetSocketAddress addr;
52	  private final InetSocketAddress lifelineAddr;
53	  private InetSocketAddress zkfcAddr;
54	  private NodeFencer fencer;
55	  private BadFencingConfigurationException fenceConfigError;
56	  private HdfsConfiguration targetConf;
57	  private String nnId;
58	  private String nsId;
59	  private boolean autoFailoverEnabled;
60	
61	  /**
62	   * Create a NNHAServiceTarget for a namenode.
63	   * Look up addresses from configuration.
64	   *
65	   * @param conf          HDFS configuration.
66	   * @param nsId          nsId of this nn.
67	   * @param nnId          nnId of this nn.
68	   */
69	  public NNHAServiceTarget(Configuration conf,
70	      String nsId, String nnId) {
71	    initializeNnConfig(conf, nsId, nnId);
72	
73	    String serviceAddr =
74	        DFSUtil.getNamenodeServiceAddr(targetConf, nsId, nnId);
75	    if (serviceAddr == null) {
76	      throw new IllegalArgumentException(
77	          "Unable to determine service address for namenode '" + nnId + "'");
78	    }
79	
80	    this.addr = NetUtils.createSocketAddr(serviceAddr,
81	        HdfsClientConfigKeys.DFS_NAMENODE_RPC_PORT_DEFAULT);
82	
83	    String lifelineAddrStr =
84	        DFSUtil.getNamenodeLifelineAddr(targetConf, nsId, nnId);
85	    this.lifelineAddr = (lifelineAddrStr != null) ?
86	        NetUtils.createSocketAddr(lifelineAddrStr) : null;
87	
88	    initializeFailoverConfig();
89	  }
90	
91	  /**
92	   * Create a NNHAServiceTarget for a namenode.
93	   * Addresses are provided so we don't need to lookup the config.
94	   *
95	   * @param conf          HDFS configuration.
96	   * @param nsId          nsId of this nn.
97	   * @param nnId          nnId of this nn.
98	   * @param addr          Provided service address.
99	   * @param lifelineAddr  Provided lifeline address.
100	   */
101	  public NNHAServiceTarget(Configuration conf,
102	      String nsId, String nnId,
103	      String addr, String lifelineAddr) {
104	    initializeNnConfig(conf, nsId, nnId);
105	
106	    this.addr = NetUtils.createSocketAddr(addr);
107	    this.lifelineAddr = NetUtils.createSocketAddr(lifelineAddr);
108	
109	    initializeFailoverConfig();
110	  }
111	
112	  private void initializeNnConfig(Configuration conf,
113	      String providedNsId, String providedNnId) {
114	    Preconditions.checkNotNull(providedNnId);
115	
116	    if (providedNsId == null) {
117	      providedNsId = DFSUtil.getOnlyNameServiceIdOrNull(conf);
118	      if (providedNsId == null) {
119	        String errorString = "Unable to determine the name service ID.";
120	        String[] dfsNames = conf.getStrings(DFS_NAMESERVICES);
121	        if ((dfsNames != null) && (dfsNames.length > 1)) {
122	          errorString = "Unable to determine the name service ID. " +
123	              "This is an HA configuration with multiple name services " +
124	              "configured. " + DFS_NAMESERVICES + " is set to " +
125	              Arrays.toString(dfsNames) + ". Please re-run with the -ns option.";
126	        }
127	        throw new IllegalArgumentException(errorString);
128	      }
129	    }
130	
131	    // Make a copy of the conf, and override configs based on the
132	    // target node -- not the node we happen to be running on.
133	    this.targetConf = new HdfsConfiguration(conf);
134	    NameNode.initializeGenericKeys(targetConf, providedNsId, providedNnId);
135	
136	    this.nsId = providedNsId;
137	    this.nnId = providedNnId;
138	  }
139	
140	  private void initializeFailoverConfig() {
141	    this.autoFailoverEnabled = targetConf.getBoolean(
142	        DFSConfigKeys.DFS_HA_AUTO_FAILOVER_ENABLED_KEY,
143	        DFSConfigKeys.DFS_HA_AUTO_FAILOVER_ENABLED_DEFAULT);
144	    if (autoFailoverEnabled) {
145	      int port = DFSZKFailoverController.getZkfcPort(targetConf);
146	      if (port != 0) {
147	        setZkfcPort(port);
148	      }
149	    }
150	
151	    try {
152	      this.fencer = NodeFencer.create(targetConf,
153	          DFSConfigKeys.DFS_HA_FENCE_METHODS_KEY);
154	    } catch (BadFencingConfigurationException e) {
155	      this.fenceConfigError = e;
156	    }
157	  }
158	
159	  /**
160	   * @return the NN's IPC address.
161	   */
162	  @Override
163	  public InetSocketAddress getAddress() {
164	    return addr;
165	  }
166	
167	  @Override
168	  public InetSocketAddress getHealthMonitorAddress() {
169	    return lifelineAddr;
170	  }
171	
172	  @Override
173	  public InetSocketAddress getZKFCAddress() {
174	    Preconditions.checkState(autoFailoverEnabled,
175	        "ZKFC address not relevant when auto failover is off");
176	    assert zkfcAddr != null;
177	    
178	    return zkfcAddr;
179	  }
180	  
181	  void setZkfcPort(int port) {
182	    assert autoFailoverEnabled;
183	          
184	    this.zkfcAddr = new InetSocketAddress(addr.getAddress(), port);
185	  }
186	
187	  @Override
188	  public void checkFencingConfigured() throws BadFencingConfigurationException {
189	    if (fenceConfigError != null) {
190	      throw fenceConfigError;
191	    }
192	    if (fencer == null) {
193	      throw new BadFencingConfigurationException(
194	          "No fencer configured for " + this);
195	    }
196	  }
197	  
198	  @Override
199	  public NodeFencer getFencer() {
200	    return fencer;
201	  }
202	  
203	  @Override
204	  public String toString() {
205	    return "NameNode at " + (lifelineAddr != null ? lifelineAddr : addr);
206	  }
207	
208	  public String getNameServiceId() {
209	    return this.nsId;
210	  }
211	  
212	  public String getNameNodeId() {
213	    return this.nnId;
214	  }
215	
216	  @Override
217	  protected void addFencingParameters(Map<String, String> ret) {
218	    super.addFencingParameters(ret);
219	    
220	    ret.put(NAMESERVICE_ID_KEY, getNameServiceId());
221	    ret.put(NAMENODE_ID_KEY, getNameNodeId());
222	  }
223	
224	  @Override
225	  public boolean isAutoFailoverEnabled() {
226	    return autoFailoverEnabled;
227	  }
228	
229	  @Override
230	  public boolean supportObserver() {
231	    return true;
232	  }
233	}
