51	/**
52	 * The {@link Router} periodically checks the state of a Namenode (usually on
53	 * the same server) and reports their high availability (HA) state and
54	 * load/space status to the
55	 * {@link org.apache.hadoop.hdfs.server.federation.store.StateStoreService}
56	 * . Note that this is an optional role as a Router can be independent of any
57	 * subcluster.
58	 * <p>
59	 * For performance with Namenode HA, the Router uses the high availability state
60	 * information in the State Store to forward the request to the Namenode that is
61	 * most likely to be active.
62	 * <p>
63	 * Note that this service can be embedded into the Namenode itself to simplify
64	 * the operation.
65	 */
66	public class NamenodeHeartbeatService extends PeriodicService {
67	
68	  private static final Logger LOG =
69	      LoggerFactory.getLogger(NamenodeHeartbeatService.class);
70	
71	
72	  /** Configuration for the heartbeat. */
73	  private Configuration conf;
74	
75	  /** Router performing the heartbeating. */
76	  private final ActiveNamenodeResolver resolver;
77	
78	  /** Interface to the tracked NN. */
79	  private final String nameserviceId;
80	  private final String namenodeId;
81	
82	  /** Namenode HA target. */
83	  private NNHAServiceTarget localTarget;
84	  /** Cache HA protocol. */
85	  private HAServiceProtocol localTargetHAProtocol;
86	  /** RPC address for the namenode. */
87	  private String rpcAddress;
88	  /** Service RPC address for the namenode. */
89	  private String serviceAddress;
90	  /** Service RPC address for the namenode. */
91	  private String lifelineAddress;
92	  /** HTTP address for the namenode. */
93	  private String webAddress;
94	  /** Connection factory for JMX calls. */
95	  private URLConnectionFactory connectionFactory;
96	  /** URL scheme to use for JMX calls. */
97	  private String scheme;
98	
99	  private String resolvedHost;
100	  private String originalNnId;
101	  /**
102	   * Create a new Namenode status updater.
103	   * @param resolver Namenode resolver service to handle NN registration.
104	   * @param nsId Identifier of the nameservice.
105	   * @param nnId Identifier of the namenode in HA.
106	   */
107	  public NamenodeHeartbeatService(
108	      ActiveNamenodeResolver resolver, String nsId, String nnId) {
109	    super(NamenodeHeartbeatService.class.getSimpleName() +
110	        (nsId == null ? "" : " " + nsId) +
111	        (nnId == null ? "" : " " + nnId));
112	
113	    this.resolver = resolver;
114	
115	    this.nameserviceId = nsId;
116	    this.namenodeId = nnId;
117	  }
118	
119	  /**
120	   * Create a new Namenode status updater.
121	   *
122	   * @param resolver Namenode resolver service to handle NN registration.
123	   * @param nsId          Identifier of the nameservice.
124	   * @param nnId          Identifier of the namenode in HA.
125	   * @param resolvedHost  resolvedHostname for this specific namenode.
126	   */
127	  public NamenodeHeartbeatService(
128	      ActiveNamenodeResolver resolver, String nsId, String nnId, String resolvedHost) {
129	    super(getNnHeartBeatServiceName(nsId, nnId));
130	
131	    this.resolver = resolver;
132	
133	    this.nameserviceId = nsId;
134	    // Concat a uniq id from original nnId and resolvedHost
135	    this.namenodeId = nnId + "-" + resolvedHost;
136	    this.resolvedHost = resolvedHost;
137	    // Same the original nnid to get the ports from config.
138	    this.originalNnId = nnId;
139	
140	  }
141	
142	  @Override
143	  protected void serviceInit(Configuration configuration) throws Exception {
144	
145	    this.conf = DFSHAAdmin.addSecurityConfiguration(configuration);
146	
147	    String nnDesc = nameserviceId;
148	    if (this.namenodeId != null && !this.namenodeId.isEmpty()) {
149	      nnDesc += "-" + namenodeId;
150	    } else {
151	      this.localTarget = null;
152	    }
153	
154	    if (originalNnId == null) {
155	      originalNnId = namenodeId;
156	    }
157	    // Get the RPC address for the clients to connect
158	    this.rpcAddress = getRpcAddress(conf, nameserviceId, originalNnId);
159	
160	    // Get the Service RPC address for monitoring
161	    this.serviceAddress =
162	        DFSUtil.getNamenodeServiceAddr(conf, nameserviceId, originalNnId);
163	    if (this.serviceAddress == null) {
164	      LOG.error("Cannot locate RPC service address for NN {}, " +
165	          "using RPC address {}", nnDesc, this.rpcAddress);
166	      this.serviceAddress = this.rpcAddress;
167	    }
168	
169	    // Get the Lifeline RPC address for faster monitoring
170	    this.lifelineAddress =
171	        DFSUtil.getNamenodeLifelineAddr(conf, nameserviceId, originalNnId);
172	    if (this.lifelineAddress == null) {
173	      this.lifelineAddress = this.serviceAddress;
174	    }
175	
176	    // Get the Web address for UI
177	    this.webAddress =
178	        DFSUtil.getNamenodeWebAddr(conf, nameserviceId, originalNnId);
179	
180	    if (resolvedHost != null) {
181	      // Get the addresses from resolvedHost plus the configured ports.
182	      rpcAddress = resolvedHost + ":"
183	          + NetUtils.getPortFromHostPortString(rpcAddress);
184	      serviceAddress = resolvedHost + ":"
185	          + NetUtils.getPortFromHostPortString(serviceAddress);
186	      lifelineAddress = resolvedHost + ":"
187	          + NetUtils.getPortFromHostPortString(lifelineAddress);
188	      webAddress = resolvedHost + ":"
189	          + NetUtils.getPortFromHostPortString(webAddress);
190	    }
191	
192	    LOG.info("{} RPC address: {}", nnDesc, rpcAddress);
193	    LOG.info("{} Service RPC address: {}", nnDesc, serviceAddress);
194	    LOG.info("{} Lifeline RPC address: {}", nnDesc, lifelineAddress);
195	    LOG.info("{} Web address: {}", nnDesc, webAddress);
196	
197	    if (this.namenodeId != null && !this.namenodeId.isEmpty()) {
198	      this.localTarget = new NNHAServiceTarget(
199	          conf, nameserviceId, namenodeId, serviceAddress, lifelineAddress);
200	    }
201	
202	    this.connectionFactory =
203	        URLConnectionFactory.newDefaultURLConnectionFactory(conf);
204	
205	    this.scheme =
206	        DFSUtil.getHttpPolicy(conf).isHttpEnabled() ? "http" : "https";
207	
208	    this.setIntervalMs(conf.getLong(
209	        DFS_ROUTER_HEARTBEAT_INTERVAL_MS,
210	        DFS_ROUTER_HEARTBEAT_INTERVAL_MS_DEFAULT));
211	
212	
213	    super.serviceInit(configuration);
214	  }
215	
216	  @Override
217	  public void periodicInvoke() {
218	    updateState();
219	  }
220	
221	  /**
222	   * Get the RPC address for a Namenode.
223	   * @param conf Configuration.
224	   * @param nsId Name service identifier.
225	   * @param nnId Name node identifier.
226	   * @return RPC address in format hostname:1234.
227	   */
228	  private static String getRpcAddress(
229	      Configuration conf, String nsId, String nnId) {
230	
231	    // Get it from the regular RPC setting
232	    String confKey = DFSConfigKeys.DFS_NAMENODE_RPC_ADDRESS_KEY;
233	    String ret = conf.get(confKey);
234	
235	    if (nsId != null || nnId != null) {
236	      // Get if for the proper nameservice and namenode
237	      confKey = DFSUtil.addKeySuffixes(confKey, nsId, nnId);
238	      ret = conf.get(confKey);
239	
240	      // If not available, get it from the map
241	      if (ret == null) {
242	        Map<String, InetSocketAddress> rpcAddresses =
243	            DFSUtil.getRpcAddressesForNameserviceId(conf, nsId, null);
244	        InetSocketAddress sockAddr = null;
245	        if (nnId != null) {
246	          sockAddr = rpcAddresses.get(nnId);
247	        } else if (rpcAddresses.size() == 1) {
248	          // Get the only namenode in the namespace
249	          sockAddr = rpcAddresses.values().iterator().next();
250	        }
251	        if (sockAddr != null) {
252	          InetAddress addr = sockAddr.getAddress();
253	          ret = addr.getHostName() + ":" + sockAddr.getPort();
254	        }
255	      }
256	    }
257	    return ret;
258	  }
259	
260	  /**
261	   * Update the state of the Namenode.
262	   */
263	  private void updateState() {
264	    NamenodeStatusReport report = getNamenodeStatusReport();
265	    if (!report.registrationValid()) {
266	      // Not operational
267	      LOG.error("Namenode is not operational: {}", getNamenodeDesc());
268	    } else if (report.haStateValid()) {
269	      // block and HA status available
270	      LOG.debug("Received service state: {} from HA namenode: {}",
271	          report.getState(), getNamenodeDesc());
272	    } else if (localTarget == null) {
273	      // block info available, HA status not expected
274	      LOG.debug(
275	          "Reporting non-HA namenode as operational: " + getNamenodeDesc());
276	    } else {
277	      // block info available, HA status should be available, but was not
278	      // fetched do nothing and let the current state stand
279	      return;
280	    }
281	    try {
282	      if (!resolver.registerNamenode(report)) {
283	        LOG.warn("Cannot register namenode {}", report);
284	      }
285	    } catch (IOException e) {
286	      LOG.info("Cannot register namenode in the State Store");
287	    } catch (Exception ex) {
288	      LOG.error("Unhandled exception updating NN registration for {}",
289	          getNamenodeDesc(), ex);
290	    }
291	  }
292	
293	  /**
294	   * Get the status report for the Namenode monitored by this heartbeater.
295	   * @return Namenode status report.
296	   */
297	  protected NamenodeStatusReport getNamenodeStatusReport() {
298	    NamenodeStatusReport report = new NamenodeStatusReport(nameserviceId,
299	        namenodeId, rpcAddress, serviceAddress,
300	        lifelineAddress, scheme, webAddress);
301	
302	    try {
303	      LOG.debug("Probing NN at service address: {}", serviceAddress);
304	
305	      URI serviceURI = new URI("hdfs://" + serviceAddress);
306	      // Read the filesystem info from RPC (required)
307	      NamenodeProtocol nn = NameNodeProxies
308	          .createProxy(this.conf, serviceURI, NamenodeProtocol.class)
309	          .getProxy();
310	
311	      if (nn != null) {
312	        NamespaceInfo info = nn.versionRequest();
313	        if (info != null) {
314	          report.setNamespaceInfo(info);
315	        }
316	      }
317	      if (!report.registrationValid()) {
318	        return report;
319	      }
320	
321	      // Check for safemode from the client protocol. Currently optional, but
322	      // should be required at some point for QoS
323	      try {
324	        ClientProtocol client = NameNodeProxies
325	            .createProxy(this.conf, serviceURI, ClientProtocol.class)
326	            .getProxy();
327	        if (client != null) {
328	          boolean isSafeMode = client.setSafeMode(
329	              SafeModeAction.SAFEMODE_GET, false);
330	          report.setSafeMode(isSafeMode);
331	        }
332	      } catch (Exception e) {
333	        LOG.error("Cannot fetch safemode state for {}", getNamenodeDesc(), e);
334	      }
335	
336	      // Read the stats from JMX (optional)
337	      updateJMXParameters(webAddress, report);
338	
339	      if (localTarget != null) {
340	        // Try to get the HA status
341	        try {
342	          // Determine if NN is active
343	          // TODO: dynamic timeout
344	          if (localTargetHAProtocol == null) {
345	            localTargetHAProtocol = localTarget.getProxy(conf, 30*1000);
346	          }
347	          HAServiceStatus status = localTargetHAProtocol.getServiceStatus();
348	          report.setHAServiceState(status.getState());
349	        } catch (Throwable e) {
350	          if (e.getMessage().startsWith("HA for namenode is not enabled")) {
351	            LOG.error("HA for {} is not enabled", getNamenodeDesc());
352	            localTarget = null;
353	          } else {
354	            // Failed to fetch HA status, ignoring failure
355	            LOG.error("Cannot fetch HA status for {}: {}",
356	                getNamenodeDesc(), e.getMessage(), e);
357	          }
358	          localTargetHAProtocol = null;
359	        }
360	      }
361	    } catch(IOException e) {
362	      LOG.error("Cannot communicate with {}: {}",
363	          getNamenodeDesc(), e.getMessage());
364	    } catch(Throwable e) {
365	      // Generic error that we don't know about
366	      LOG.error("Unexpected exception while communicating with {}: {}",
367	          getNamenodeDesc(), e.getMessage(), e);
368	    }
369	    return report;
370	  }
371	
372	  /**
373	   * Get the description of the Namenode to monitor.
374	   * @return Description of the Namenode to monitor.
375	   */
376	  public String getNamenodeDesc() {
377	    if (namenodeId != null && !namenodeId.isEmpty()) {
378	      return nameserviceId + "-" + namenodeId + ":" + serviceAddress;
379	    } else {
380	      return nameserviceId + ":" + serviceAddress;
381	    }
382	  }
383	
384	  private static String getNnHeartBeatServiceName(String nsId, String nnId) {
385	    return NamenodeHeartbeatService.class.getSimpleName() +
386	        (nsId == null ? "" : " " + nsId) +
387	        (nnId == null ? "" : " " + nnId);
388	  }
389	
390	  /**
391	   * Get the parameters for a Namenode from JMX and add them to the report.
392	   * @param address Web interface of the Namenode to monitor.
